import{_ as t,o as a,c as r,a as i}from"./app.CYXXef1p.js";const g=JSON.parse('{"title":"Thegent Orchestration Optimization Program (v1.0)","description":"","frontmatter":{},"headers":[],"relativePath":"ORCHESTRATION.md","filePath":"ORCHESTRATION.md","lastUpdated":1771753292000}'),o={name:"ORCHESTRATION.md"};function n(s,e,l,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="thegent-orchestration-optimization-program-v1-0" tabindex="-1">Thegent Orchestration Optimization Program (v1.0) <a class="header-anchor" href="#thegent-orchestration-optimization-program-v1-0" aria-label="Permalink to &quot;Thegent Orchestration Optimization Program (v1.0)&quot;">​</a></h1><p>This document summarizes the unified orchestration architecture implemented for <code>thegent</code>.</p><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h2><h3 id="_1-unified-execution-lifecycle-phase-1" tabindex="-1">1. Unified Execution Lifecycle (Phase 1) <a class="header-anchor" href="#_1-unified-execution-lifecycle-phase-1" aria-label="Permalink to &quot;1. Unified Execution Lifecycle (Phase 1)&quot;">​</a></h3><ul><li><strong>Run IDs &amp; Correlation</strong>: Every action is tracked with a unique <code>run_id</code> and optional <code>correlation_id</code>.</li><li><strong>Run Registry</strong>: A persistent JSONL store of all execution metadata, including start/end events, durations, and exit codes.</li><li><strong>Telemetry Contracts</strong>: Standardized fields for agent, model, lane, and confidence.</li></ul><h3 id="_2-dependency-aware-dag-orchestration-phase-1-2" tabindex="-1">2. Dependency-aware DAG Orchestration (Phase 1 &amp; 2) <a class="header-anchor" href="#_2-dependency-aware-dag-orchestration-phase-1-2" aria-label="Permalink to &quot;2. Dependency-aware DAG Orchestration (Phase 1 &amp; 2)&quot;">​</a></h3><ul><li><strong>Routing Engine</strong>: Executes tasks in parallel based on their dependencies.</li><li><strong>Quorum &amp; Arbitration</strong>: Supports multi-agent consensus for critical tasks.</li><li><strong>Confidence-aware Routing</strong>: Automatically escalates low-confidence tasks to 2-agent quorum.</li><li><strong>Evidence Capture</strong>: Every completed task links to its execution record (session ID).</li></ul><h3 id="_3-resilience-self-healing-phase-2-5" tabindex="-1">3. Resilience &amp; Self-healing (Phase 2 &amp; 5) <a class="header-anchor" href="#_3-resilience-self-healing-phase-2-5" aria-label="Permalink to &quot;3. Resilience &amp; Self-healing (Phase 2 &amp; 5)&quot;">​</a></h3><ul><li><strong>Adaptive Retries</strong>: Exponential backoff for transient failures (e.g., rate limits).</li><li><strong>Circuit Breakers</strong>: Prevents cascading failures by isolating unstable agents or models.</li><li><strong>Checkpoint/Rollback</strong>: Immutable point-in-time snapshots of DAG state.</li><li><strong>Auto-Reconciliation</strong>: Automatically recovers from crashes by syncing DAG state with live OS processes on restart.</li></ul><h3 id="_4-governance-security-phase-3" tabindex="-1">4. Governance &amp; Security (Phase 3) <a class="header-anchor" href="#_4-governance-security-phase-3" aria-label="Permalink to &quot;4. Governance &amp; Security (Phase 3)&quot;">​</a></h3><ul><li><strong>Policy Engine</strong>: Enforces rules based on environment (e.g., trust score gates in production).</li><li><strong>Signed Artifacts</strong>: Cryptographic signatures ensure the integrity of the run registry.</li><li><strong>Immutable Audit Trail</strong>: Verifiable history of all orchestration actions.</li><li><strong>Governance Overrides</strong>: Authorized bypass for critical recovery with mandatory rationale.</li></ul><h3 id="_5-operator-cockpit-ux-phase-4" tabindex="-1">5. Operator Cockpit &amp; UX (Phase 4) <a class="header-anchor" href="#_5-operator-cockpit-ux-phase-4" aria-label="Permalink to &quot;5. Operator Cockpit &amp; UX (Phase 4)&quot;">​</a></h3><ul><li><strong>Cockpit Summary</strong>: High-level overview of session health and resource states.</li><li><strong>Decision Replay</strong>: Detailed rationales stored for every execution failure.</li><li><strong>One-click Fallbacks</strong>: Simplified recovery through automated agent swapping.</li><li><strong>Feedback Loops</strong>: Operator-driven confidence calibration.</li></ul><h2 id="cli-command-reference" tabindex="-1">CLI Command Reference <a class="header-anchor" href="#cli-command-reference" aria-label="Permalink to &quot;CLI Command Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>thegent cockpit</code></td><td>High-level orchestration health summary</td></tr><tr><td><code>thegent history list</code></td><td>View recent execution runs</td></tr><tr><td><code>thegent history verify</code></td><td>Audit registry integrity</td></tr><tr><td><code>thegent dag run</code></td><td>Execute DAG with auto-reconciliation</td></tr><tr><td><code>thegent dag sync --watch</code></td><td>Health-monitoring loop for active tasks</td></tr><tr><td><code>thegent dag checkpoint</code></td><td>Create state snapshot</td></tr><tr><td><code>thegent benchmark</code></td><td>Latency and success rate metrics</td></tr><tr><td><code>thegent archive</code></td><td>Cleanup old session data</td></tr></tbody></table><h2 id="status-v1-0-ready" tabindex="-1">Status: v1.0 Ready <a class="header-anchor" href="#status-v1-0-ready" aria-label="Permalink to &quot;Status: v1.0 Ready&quot;">​</a></h2><p>The orchestration program is fully integrated, hardened, and ready for production use.</p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul>',20)])])}const p=t(o,[["render",n]]);export{g as __pageData,p as default};
